(31, 837, NULL, 0, 'Nguyễn Thị Lan', 'lan.nguyen@gmail.com', '0901122334', 'Rất hài lòng', 'Muối ớt thơm, cay vừa phải, dùng chấm thịt nướng rất hợp. Sẽ mua lại.', 5, 0, '2026-08-20 09:37:23', 1),
(32, 837, NULL, 0, 'Trần Văn Hùng', 'hungtran@yahoo.com', '0912233445', 'Giao hàng nhanh', 'Đóng gói cẩn thận, ship đúng hẹn. Vị muối đậm đà, gia đình mình thích.', 5, 0, '2026-08-20 06:37:23', 1),
(33, 835, NULL, 0, 'Lê Minh Châu', 'chauminh@email.com', '0988112233', 'Hơi cay với trẻ nhỏ', 'Bột ớt siêu cay đúng nghĩa. Người lớn ăn ổn, trẻ em nên pha loãng.', 4, 0, '2026-08-20 03:37:23', 1),
(34, 835, NULL, 0, 'Phạm Quốc Bảo', 'bao.pham@corp.vn', '0933445566', '', 'Dùng làm kimchi tại nhà, màu đẹp và thơm. Giá hợp lý so với siêu thị.', 5, 0, '2026-08-19 11:37:23', 0),
(35, 834, NULL, 0, 'Hoàng Yến Nhi', 'nhihoang@gmail.com', '0977001122', 'Cay vừa ăn', 'Bột ớt cay vừa, không gắt cổ. Rắc lên mì trộn rất ngon.', 4, 0, '2026-08-19 11:37:23', 1),
(36, 833, NULL, 0, 'Vũ Đức Thành', 'thanhvu@biz.vn', '0909556677', 'Vị mặn dễ dùng', 'Bột ớt mặn tiện nêm canh. Bao bì kín, để lâu không ẩm.', 5, 0, '2026-08-18 11:37:23', 1),
(37, 832, NULL, 0, 'Đỗ Thanh Trúc', 'trucdo@outlook.com', '0866009988', 'Vảy ớt đẹp', 'Vảy ớt nhìn bắt mắt, rắc lên pizza Hàn rất ổn. Chỉ hơi ít so với giá.', 3, 0, '2026-08-18 11:37:23', 0),
(38, 831, NULL, 0, 'Bùi Hải Đăng', 'dangbui@company.vn', '0944112233', 'Củ cải tươi Jeju', 'Củ cải giòn, ngọt nhẹ. Ăn kèm thịt ba chỉ tuyệt. Sẽ order sỉ cho quán.', 5, 0, '2026-08-17 11:37:23', 1),
(39, 829, NULL, 0, 'Ngô Thị Mai', 'maingo@mail.com', '0922003344', 'Cắt thanh tiện lợi', 'Củ cải muối vàng cắt thanh sẵn, mở ra dùng luôn. Vị chuẩn Hàn.', 5, 0, '2026-08-17 11:37:23', 1),
(40, 828, NULL, 0, 'Lý Văn Phong', 'phongly@gmail.com', '0912887766', 'Cắt lát hơi dày', 'Vị ngon nhưng miếng hơi dày với khẩu vị nhà mình. Vẫn cho 4 sao.', 4, 0, '2026-08-16 11:37:23', 1),
(41, 826, NULL, 0, 'Mai Thị Hương', 'huongmai@email.com', '0901778899', 'Càng lẻ trắng sạch', 'Càng lẻ củ cải trắng tươi, không hôi. Dùng nấu canh rất ngọt nước.', 5, 0, '2026-08-15 11:37:23', 0),
(42, 825, NULL, 0, 'Đinh Công Minh', 'minhdinh@corp.com', '0988112233', 'Kimchi củ cải nước', 'Nước kimchi chua nhẹ, giải ngấy. Ăn kèm cơm trắng là hết veo.', 5, 0, '2026-08-15 11:37:23', 1),
(43, 824, NULL, 0, 'Tạ Thu Hà', 'hata@yahoo.com', '0933556677', 'Lá mè ngâm tương', 'Mùi nước tương thơm, lá mè không nát. Hợp làm khai vị.', 4, 0, '2026-08-14 11:37:23', 1),
(44, 823, NULL, 0, 'Châu Anh Tú', 'tuchau@biz.vn', '0977114455', 'Kimchi lá mè', 'Lần đầu ăn kimchi lá mè, bất ngờ vì ngon. Cay dịu, không quá chua.', 5, 0, '2026-08-13 11:37:23', 1),
(45, 822, NULL, 0, 'Hồ Ngọc Ánh', 'anhho@gmail.com', '0909332211', 'Bắp giò hầm mềm', 'Khoanh bắp giò hầm mềm, nước sốt đậm. Chỉ cần hâm lại là ăn được.', 5, 0, '2026-08-12 11:37:23', 0),
(46, 820, NULL, 0, 'Phan Văn Khoa', 'khoaphan@company.vn', '0911667788', 'Chân giò hầm', 'Chân giò mềm, ít mỡ. Phần nước dùng nấu mì rất hợp. Đóng gói sạch sẽ.', 4, 0, '2026-08-11 11:37:23', 1),
(47, 819, NULL, 0, 'Trương Mỹ Linh', 'linhtruong@mail.com', '0866223344', 'Rau tiến vua', 'Rau tiến vua ngâm tương lạ miệng, giòn. Hộp hơi nhỏ so với mong đợi.', 3, 0, '2026-08-10 11:37:23', 1),
(48, 778, NULL, 0, 'Kiều Đức Long', 'longkieu@email.com', '0944551122', 'Sản phẩm ổn định', 'Mua lần 3 vẫn chất lượng như lần đầu. Shop tư vấn nhiệt tình.', 5, 0, '2026-08-09 11:37:23', 1),
