(205, 443, '', 3, 1, 'NỀN TẢNG KHÁC', '', '', 0, 0, 'div', '<ul>\r\n	<li>Facebook</li>\r\n	<li>Instagram</li>\r\n	<li>TikTok</li>\r\n	<li>Shopee</li>\r\n	<li>Lazada</li>\r\n</ul>\r\n', '', '', 573, 'vi', '1776331238'),
(196, 68, 'demo/anh-lookbook-thoi-trang_113854100.jpg', 1, 1, 'Slide 1', '', '', 0, 0, 'div', '', '', '', 555, 'vi', '1776329456'),
(197, 372, '', 2, 1, 'Thanh toán qua ngân hàng', '', '', 0, 0, 'div', '<p>Kh&aacute;ch h&agrave;ng c&oacute; thể thanh to&aacute;n bằng chuyển khoản ng&acirc;n h&agrave;ng trực tuyến hoặc qua v&iacute; điện tử sau khi đặt h&agrave;ng th&agrave;nh c&ocirc;ng.</p>\r\n\r\n<p><img alt=\"\" src=\"http://demo22.phuongnamvina.com//img_data/images/maxresdefault.jpg\" style=\"width: 100%;\" /></p>\r\n', '', '', 556, 'vi', '1726210971'),
(287, 443, '', 5, 1, '', '', '', 0, 0, 'div', '<p><img alt=\"\" src=\"/img_data/images/payment_momo.png\" style=\"width: 65px; height: 30px;\" />&nbsp;<img alt=\"\" src=\"/img_data/images/payment_zalopay.png\" style=\"width: 65px; height: 30px;\" />&nbsp;</p>\r\n\r\n<p>&nbsp;<img alt=\"\" src=\"/img_data/images/payment_visa.png\" style=\"width: 65px; height: 30px;\" />&nbsp;<img alt=\"\" src=\"/img_data/images/payment_atm.png\" style=\"width: 65px; height: 30px;\" /></p>\r\n\r\n<p><img alt=\"\" src=\"http://demo33.phuongnamvina.com//img_data/images/bo_cong_thuong.png\" style=\"width: 186px;\" /></p>\r\n', '', '', 728, 'ko', '1776330125'),
(200, 372, '', 1, 1, 'Thanh toán khi nhận hàng', '', '', 0, 0, 'div', '<p>Kh&aacute;ch h&agrave;ng sẽ thanh to&aacute;n ngay sau khi nhận được h&agrave;ng bằng phương thức thanh to&aacute;n khi nhận h&agrave;ng (COD).</p>\r\n', '', '', 559, 'vi', '1726211775'),
(231, 443, '', 2, 1, 'DANH MỤC', '', '', 0, 0, 'div', '<ul>\r\n	<li>&Aacute;o</li>\r\n	<li>Ch&acirc;n v&aacute;y</li>\r\n	<li>&Aacute;o kho&aacute;c</li>\r\n	<li>Đầm/ V&aacute;y</li>\r\n	<li>Quần</li>\r\n	<li>Quần jeans INSERT INTO `db_dathang` (`id`, `ma_dh`, `id_thanhvien`, `ho_ten`, `dien_thoai`, `email`, `so_nha`, `phuong`, `quan`, `thanh_pho`, `dia_chi`, `loi_nhan`, `thanh_toan`, `phi_vanchuyen`, `ma_giamgia`, `so_tien_giam`, `ngay_dathang`, `tinhtrang_donhang`, `trangthai_xuly`, `trangthai_thanhtoan`, `ngay_capnhat`, `ngay_thanhtoan`, `has_box`, `phi_thung`, `pancake_order_id`) VALUES
