INSERT INTO `db_lienhe` (`id`, `ho_ten`, `email`, `so_dien_thoai`, `dia_chi`, `tieu_de`, `noi_dung`, `ngay_gui`, `da_xem`) VALUES
(67, 'Bùi Thanh Mai', 'maibui@gmail.com', '0911002233', '67 Lý Thường Kiệt, Nha Trang', 'Câu hỏi dinh dưỡng', 'Sản phẩm có dùng chất bảo quản không? Phù hợp cho người ăn chay được không ạ?', '2026-08-12 02:58:46', 1),
(66, 'Đặng Quốc Huy', 'huy.dang@biz.vn', '0866123456', '101 Võ Văn Tần, Q.3, TP.HCM', 'Menu cho sự kiện', 'Chúng tôi tổ chức sự kiện 200 khách, cần set menu đồ ăn kèm kimchi. Xin báo giá combo.', '2026-08-14 02:58:46', 0),
(65, 'Võ Thị Phương', 'phuongvo@email.com', '0909887766', '9 Nguyễn Văn Cừ, Cần Thơ', 'Kiểm tra đơn hàng', 'Tôi đã đặt hàng tuần trước nhưng chưa nhận được. Mã đơn: DH20260315. Nhờ kiểm tra giúp.', '2026-08-16 02:58:46', 1),
(64, 'Hoàng Đức Em', 'hoangducem@gmail.com', '0977112233', '15 Phan Chu Trinh, Huế', 'Hợp tác phân phối', 'Công ty chúng tôi muốn trở thành đại lý phân phối tại khu vực miền Trung. Xin liên hệ để trao đổi.', '2026-08-17 02:58:46', 0),
(63, 'Phạm Thu Dung', 'dungpham@outlook.com', '0934567890', '22 Hai Bà Trưng, Đà Nẵng', 'Góp ý website', 'Website load hơi chậm trên mobile. Mong team cải thiện trải nghiệm người dùng.', '2026-08-18 02:58:46', 1),
(62, 'Lê Minh Cường', 'cuong.le@company.vn', '0987654321', '88 Trần Hưng Đạo, Hà Nội', 'Đặt hàng số lượng lớn', 'Chúng tôi cần đặt khoảng 50 thùng kimchi/tháng. Xin gửi báo giá chi tiết và chính sách chiết khấu.', '2026-08-19 02:58:46', 0),
(61, 'Trần Thị Bình', 'tranthibinh@yahoo.com', '0912345678', '45 Lê Lợi, Q.3, TP.HCM', 'Hỏi về giao hàng', 'Cho tôi hỏi phí ship nội thành và thời gian giao hàng trung bình là bao lâu ạ?', '2026-08-19 21:58:46', 0),
(60, 'Nguyễn Văn An', 'nguyenvanan@gmail.com', '0901234567', '12 Nguyễn Huệ, Q.1, TP.HCM', 'Tư vấn sản phẩm kimchi', 'Xin chào, tôi muốn tìm hiểu về các dòng sản phẩm kimchi và bảng giá sỉ cho nhà hàng. Mong được phản hồi sớm.', '2026-08-20 00:58:46', 0),
(70, 'Nguyễn Thị Hoa', 'hoa.nguyen@gmail.com', '0901112233', '10 Lý Tự Trọng, Q.1, TP.HCM', 'Hỏi giờ mở cửa', 'Shop mở cửa mấy giờ ạ? Cuối tuần có ship trong ngày không?', '2026-08-20 02:59:13', 0),
(71, 'Trần Quốc Bảo', 'baotran@corp.vn', '0911223344', '55 Nguyễn Trãi, Thanh Xuân, Hà Nội', 'Báo giá sỉ tháng 8', 'Cần báo giá sỉ kimchi 5kg và 10kg, số lượng khoảng 100 thùng/tháng.', '2026-08-20 00:29:13', 0),
(69, 'Lý Hoàng Yến', 'yen.ly@mail.com', '0922334455', '28 Pasteur, Q.1, TP.HCM', 'Cảm ơn & đánh giá', 'Đã nhận hàng đúng hẹn, chất lượng tốt. Sẽ ủng hộ lâu dài. Chúc shop ngày càng phát triển!', '2026-08-08 02:58:46', 1),
(72, 'Lê Thị Kim', 'kimle@yahoo.com', '0988332211', '20 Hoàng Diệu, Hải Châu, Đà Nẵng', 'Đổi trả hàng', 'Sản phẩm giao bị móp hộp. Xin hướng dẫn quy trình đổi trả.', '2026-08-19 19:29:13', 0),
(73, 'Phạm Minh Tuấn', 'tuan.pham@email.com', '0933445566', '7 Pasteur, Q.3, TP.HCM', 'Menu set cho group', 'Nhà hàng cần set đồ ăn kèm kimchi cho bàn 10 người. Xin gửi gợi ý combo.', '2026-08-19 13:29:13', 1),
